import subprocess,json,zipfile,io,hashlib,tempfile,sys,os
from pathlib import Path,PurePosixPath
repo='JohnnyTeutonic/ember.cpp';run_id=sys.argv[1];root=Path('/home/jonat/ember_publication_20261030')
api=lambda suffix:json.loads(subprocess.check_output(['gh','api','repos/'+repo+'/'+suffix]))
run=api('actions/runs/'+run_id);arts=api('actions/runs/'+run_id+'/artifacts')['artifacts'];art=next((a for a in arts if a['name']=='wheels-ubuntu-latest-cpu'),None)
if not art:print('CPU artifact not available yet');sys.exit(3)
assert art['size_in_bytes'] <= 40_000_000, ('CPU artifact exceeds 40 MB bound',art['size_in_bytes'])
raw=subprocess.check_output(['gh','api','repos/'+repo+'/actions/artifacts/'+str(art['id'])+'/zip']);assert len(raw)<100_000_000
assert art.get('digest') in (None, 'sha256:'+hashlib.sha256(raw).hexdigest())
expected={name:subprocess.check_output(['git','show',run['head_sha']+':'+name],cwd=root) for name in ['LICENSE','THIRD_PARTY_NOTICES.md']}
result={'schema':'ember.actual_ci_wheel_artifact_audit.v1','run_id':int(run_id),'head_sha':run['head_sha'],'artifact_id':art['id'],'artifact_name':art['name'],'artifact_zip_sha256':hashlib.sha256(raw).hexdigest(),'artifact_api_digest':art.get('digest'),'wheels':[],'scope':'Actual GitHub wheel ZIP content/license and CPU-native import audit; no GPU/device/model inference or timing.'}
with zipfile.ZipFile(io.BytesIO(raw)) as outer:
 for info in outer.infolist():
  if not info.filename.endswith('.whl'):continue
  wheelraw=outer.read(info);row={'filename':info.filename,'sha256':hashlib.sha256(wheelraw).hexdigest(),'license_files':{}}
  with zipfile.ZipFile(io.BytesIO(wheelraw)) as wheel:
   for name,want in expected.items():
    matches=[n for n in wheel.namelist() if '.dist-info/' in n and PurePosixPath(n).name==name];assert len(matches)==1,(info.filename,name,matches)
    content=wheel.read(matches[0]);assert content==want,(info.filename,name)
    row['license_files'][name]={'path':matches[0],'sha256':hashlib.sha256(content).hexdigest(),'exact_source_bytes':True}
   if '-cp312-cp312-' in info.filename:
    with tempfile.TemporaryDirectory(prefix='ember_cpu_wheel_audit_') as tmp:
     for item in wheel.infolist():
      path=PurePosixPath(item.filename);assert not path.is_absolute() and '..' not in path.parts
      assert (item.external_attr>>16)&0o170000 !=0o120000
      dest=Path(tmp)/str(path)
      if item.is_dir():dest.mkdir(parents=True,exist_ok=True)
      else:dest.parent.mkdir(parents=True,exist_ok=True);dest.write_bytes(wheel.read(item))
     code='import sys,json,hashlib,pathlib;sys.path.insert(0,sys.argv[1]);import tinyllama_cpp.tinyllama_bindings as b;assert b.cuda_compiled is False;assert callable(b.TinyLlamaSession) and callable(b.ModelConfig);print(json.dumps({"cuda_compiled":b.cuda_compiled,"required_apis_callable":True,"module_sha256":hashlib.sha256(pathlib.Path(b.__file__).read_bytes()).hexdigest()}))'
     p=subprocess.run([sys.executable,'-I','-c',code,tmp],cwd=tmp,capture_output=True,text=True);assert p.returncode==0,p.stderr
     row['native_import']=json.loads(p.stdout)
  result['wheels'].append(row)
assert len(result['wheels'])==6
out=Path('/home/jonat')/('ember_actual_wheel_audit_'+run_id+'.json');out.write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({'receipt':str(out),'head_sha':run['head_sha'],'wheels':len(result['wheels']),'all_license_bytes_exact':True,'cpu312_native_import':'PASS'},indent=2))
